contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    receive() external payable {}

    fallback() external payable {}

    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(amount > 0, "amount must be positive");
        require(address(this).balance >= amount, "insufficient balance");
        require(c.owner() == address(this), "test contract must be the owner");

        // Fund c with `amount` wei. fallback() on c is payable, so this increments depositsCount.
        c.sendMoney(address(c), amount, ""); if (__ESBMC_reverted()) return;

        uint cBalBefore = address(c).balance;
        uint meBefore = address(this).balance;

        require(cBalBefore > 0, "funding failed");

        c.withdrawAll(); if (__ESBMC_reverted()) return;

        assert(address(this).balance == meBefore + cBalBefore && address(c).balance == 0);
    }
}

