// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 amount) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(amount > 0);
        vm.assume(address(this).balance >= amount);
        vm.assume(c.owner() == address(this));
        try c.sendMoney(address(c), amount, "") {} catch { return; }
        uint cBalBefore = address(c).balance;
        uint meBefore = address(this).balance;
        vm.assume(cBalBefore > 0);
        try c.withdrawAll() {} catch { return; }
        assertTrue(address(this).balance == meBefore + cBalBefore && address(c).balance == 0);
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}

    fallback() external payable {}
}
